static void rt2x00debug_create_file_driver ( const char * name , struct rt2x00debug_intf * intf , struct debugfs_blob_wrapper * blob ) { char * data ; if ( ! data ) { return ; } blob -> data = data ; data += sprintf ( data , "driver:\t%s\n" , intf -> rt2x00dev -> ops -> name ) ; data += sprintf ( data , "version:\t%s\n" , DRV_VERSION ) ; blob -> size = strlen ( blob -> data ) ; debugfs_create_blob ( name , 0400 , intf -> driver_folder , blob ) ; } 